export const FRACTIONS_ACTIVITIES = [
// PHASE A — CONCRETE (1-20): memecah benda nyata secara fisik menjadi bagian sama, menamai setengah/sepertiga/seperempat, bagian-keseluruhan dengan benda nyata
{n:1,type:"mcq",micro:"Arti pecahan",q:"Kamu memotong pizza menjadi 2 bagian sama besar dan memakan 1 bagian. Berapa pecahan pizza yang kamu makan?",options:["1/2","2/1","1/1"],answer:0,explain:"Memakan 1 dari 2 bagian sama berarti kamu memakan satu-perdua (1/2) pizza itu.",hint:"Menjadi berapa bagian sama pizza itu dipotong, dan berapa yang kamu makan?"},
{n:2,type:"mcq",micro:"Bagian sama (konkret)",q:"Sebatang cokelat dipatahkan menjadi 4 bagian sama besar. Apa nama satu bagian tunggal itu, sebagai pecahan dari keseluruhan batang?",options:["2/4","1/4","4/1"],answer:1,explain:"Setiap dari 4 bagian sama adalah satu-perempat (1/4) dari keseluruhan batang.",hint:"Jika keseluruhan batang dibagi menjadi 4 bagian sama, pecahan apa yang mewakili hanya 1 dari bagian itu?"},
{n:3,type:"tf",micro:"Syarat bagian sama",q:"Benar atau Salah: Pecahan seperti 1/2 tetap masuk akal meski bagian-bagiannya berbeda ukuran.",answer:false,explain:"Pecahan menuntut bagian berukuran sama — memotong pizza menjadi 2 bagian yang sangat berbeda ukurannya tidak benar-benar mewakili setengah.",hint:"Jika sebuah pizza dipotong menjadi 2 bagian di mana satu jauh lebih besar dari yang lain, apakah setiap bagian benar-benar 'setengah' dari pizza itu?"},
{n:4,type:"mcq",micro:"Menamai setengah",q:"Sebuah apel dipotong menjadi 2 bagian sama. Apa nama 1 dari bagian itu?",options:["Satu-pertiga","Satu-perempat","Satu-perdua (setengah)"],answer:2,explain:"Memecah sesuatu menjadi 2 bagian sama berarti setiap bagian adalah satu-perdua.",hint:"'Setengah' menggambarkan 1 bagian dari berapa bagian sama?"},
{n:5,type:"mcq",micro:"Menamai sepertiga",q:"Sebuah sandwich dipotong menjadi 3 bagian sama. Apa nama 1 dari bagian itu?",options:["Satu-pertiga","Satu-perempat","Satu-perdua"],answer:0,explain:"Memecah sesuatu menjadi 3 bagian sama berarti setiap bagian adalah satu-pertiga.",hint:"'Pertiga' menggambarkan 1 bagian dari berapa bagian sama?"},
{n:6,type:"mcq",micro:"Bagian-keseluruhan konkret",q:"Sebatang permen dibagi menjadi 4 bagian sama, dan kamu memiliki 3 di antaranya. Berapa pecahan batang itu yang kamu miliki?",options:["1/4","3/4","4/3"],answer:1,explain:"Memiliki 3 dari 4 bagian sama berarti kamu memiliki tiga-perempat (3/4) dari batang itu.",hint:"Berapa bagian sama yang membentuk keseluruhan batang, dan berapa yang benar-benar kamu miliki?"},
{n:7,type:"mcq",micro:"Keseluruhan vs pecahan",q:"Jika kamu memakan semua 4 bagian sama dari sebatang permen yang dibagi menjadi 4 bagian, berapa pecahan batang itu yang kamu makan?",options:["1/4","0/4","4/4 (keseluruhan batang)"],answer:2,explain:"Memakan semua 4 dari 4 bagian sama berarti kamu memakan seluruh batang, atau 4/4 (yang sama dengan 1 keseluruhan).",hint:"Jika kamu memakan setiap bagian, berapa banyak dari keseluruhan batang itu?"},
{n:8,type:"tf",micro:"Bagian pecahan memiliki nama",q:"Benar atau Salah: Pada pecahan 3/4, angka atas (3) memberitahumu menjadi berapa bagian sama keseluruhan itu dibagi.",answer:false,explain:"Angka bawah (penyebut, 4) adalah total bagian sama; angka atas (pembilang, 3) adalah berapa banyak dari bagian itu yang kamu miliki.",hint:"Apakah '4' pada 3/4 menggambarkan total jumlah bagian sama, atau berapa bagian yang kamu miliki?"},
{n:9,type:"mcq",micro:"Bagian-keseluruhan konkret",q:"Sebuah pizza dipotong menjadi 8 iris sama besar, dan 5 iris dimakan. Berapa pecahan pizza yang dimakan?",options:["5/8","8/5","3/8"],answer:0,explain:"Memakan 5 dari 8 iris sama berarti lima-perdelapan (5/8) pizza itu dimakan.",hint:"Berapa total iris sama yang ada, dan berapa yang benar-benar dimakan?"},
{n:10,type:"mcq",micro:"Pecahan yang tersisa",q:"Sebuah pizza dipotong menjadi 8 iris sama besar, dan 5 iris dimakan. Berapa pecahan pizza yang tersisa?",options:["8/3","3/8","5/8"],answer:1,explain:"Jika 5 dari 8 iris dimakan, 3 dari 8 iris (3/8) tersisa.",hint:"Dari 8 total iris, berapa yang TIDAK dimakan?"},
{n:11,type:"mcq",micro:"Menamai seperempat",q:"Sebuah petak taman dibagi menjadi 4 bagian sama. Apa nama 1 bagian itu, sebagai pecahan?",options:["Satu-perdua","Satu-pertiga","Satu-perempat"],answer:2,explain:"Membagi menjadi 4 bagian sama berarti setiap bagian adalah satu-perempat.",hint:"'Seperempat' menggambarkan 1 bagian dari berapa bagian sama?"},
{n:12,type:"mcq",micro:"Membandingkan setengah secara fisik",q:"Dua kue identik masing-masing dipotong menjadi 2 bagian sama. Apakah satu bagian dari Kue A dan satu bagian dari Kue B (keduanya 'setengah' dari kuenya masing-masing) berukuran sama?",options:["Ya, karena kedua kue identik dan kedua bagian tepat setengah dari keseluruhan yang identik","Tidak, setengah tidak pernah bisa dibandingkan antara kue yang berbeda","Hanya jika kedua kue dipotong dengan arah yang persis sama"],answer:0,explain:"Karena kedua kue awal itu identik, memotong masing-masing menjadi 2 bagian sama menghasilkan bagian dengan ukuran sebenarnya yang sama.",hint:"Jika kedua kue awal ukurannya persis sama, apakah setengah bagiannya juga akan sama ukurannya?"},
{n:13,type:"tf",micro:"Pecahan dari sekelompok benda (konkret)",q:"Benar atau Salah: Jika kamu punya 6 kelereng dan 2 di antaranya merah, kamu bisa menggambarkan kelereng merah itu sebagai pecahan 2/6 dari keseluruhan kelompok.",answer:true,explain:"Sebuah pecahan bisa menggambarkan bagian dari sekelompok benda, bukan hanya bagian dari satu benda tunggal — 2 merah dari 6 total kelereng adalah 2/6.",hint:"Bisakah sebuah pecahan menggambarkan 'bagian dari sekelompok', bukan hanya 'bagian dari satu benda tunggal'?"},
{n:14,type:"mcq",micro:"Pecahan dari sekelompok benda",q:"Kamu punya 10 stiker, dan 4 di antaranya berbentuk bintang. Berapa pecahan stikermu yang berbentuk bintang?",options:["6/10","4/10","10/4"],answer:1,explain:"4 dari 10 total stiker yang berbentuk bintang adalah pecahan 4/10.",hint:"Berapa total stiker yang ada, dan berapa banyak yang secara khusus berbentuk bintang?"},
{n:15,type:"mcq",micro:"Memotong menjadi seperlima",q:"Sebuah pita dipotong menjadi 5 bagian sama besar. Apa nama satu bagian tunggal itu, sebagai pecahan?",options:["Satu-perenam","Satu-perempat","Satu-perlima"],answer:2,explain:"Membagi menjadi 5 bagian sama berarti setiap bagian adalah satu-perlima.",hint:"'Perlima' menggambarkan 1 bagian dari berapa bagian sama?"},
{n:16,type:"mcq",micro:"Soal cerita konkret",q:"Sebuah kue dipotong menjadi 6 iris sama besar untuk sebuah pesta. Jika 4 iris disajikan, berapa pecahan kue yang telah disajikan?",options:["4/6","6/4","2/6"],answer:0,explain:"Menyajikan 4 dari 6 iris sama adalah pecahan 4/6.",hint:"Berapa total iris sama yang membentuk kue itu, dan berapa yang disajikan?"},
{n:17,type:"mcq",micro:"Keseluruhan yang terdiri dari bagian sama",q:"Jika sebuah pai utuh dipotong menjadi 3 bagian sama, apa yang diwakili oleh 3/3?",options:["Tidak ada bagian pai sama sekali","Keseluruhan pai (semua 3 bagian)","Hanya 1 bagian dari pai"],answer:1,explain:"3/3 berarti semua 3 dari 3 bagian sama — itu adalah keseluruhan pai.",hint:"Jika kamu memiliki setiap bagian sama, berapa banyak dari keseluruhan itu yang kamu miliki?"},
{n:18,type:"tf",micro:"Nol sebagai pecahan",q:"Benar atau Salah: Jika sebuah pizza dipotong menjadi 4 iris sama dan tidak ada yang dimakan, pecahan yang dimakan adalah 4/4.",answer:false,explain:"Tidak memakan satu pun dari 4 iris sama berarti 0 dari 4, atau 0/4 — bukan 4/4.",hint:"Jika sama sekali tidak ada yang dimakan, berapa dari 4 iris yang diwakili itu?"},
{n:19,type:"mcq",micro:"Menamai seperenam",q:"Sebatang cokelat dipatahkan menjadi 6 kotak sama besar. Apa nama 1 kotak itu, sebagai pecahan dari batang tersebut?",options:["Satu-pertujuh","Satu-perlima","Satu-perenam"],answer:2,explain:"Membagi menjadi 6 bagian sama berarti setiap bagian adalah satu-perenam.",hint:"'Perenam' menggambarkan 1 bagian dari berapa bagian sama?"},
{n:20,type:"mcq",micro:"Memeriksa deskripsi pecahan",q:"Sebuah pizza dipotong menjadi 6 iris sama, dan seseorang berkata '4 iris dimakan adalah pecahan 4/5.' Apa yang salah?",options:["Angka bawah seharusnya 6 (total iris), bukan 5, jadi seharusnya 4/6","Angka atas seharusnya 6, bukan 4","Tidak ada, 4/5 benar"],answer:0,explain:"Penyebut (angka bawah) harus cocok dengan total jumlah bagian sama — karena pizza itu total 6 iris, pecahannya harus 4/6, bukan 4/5.",hint:"Berapa total iris sama yang benar-benar dimiliki keseluruhan pizza itu?"},

// PHASE B — PICTORIAL (21-40): batang/lingkaran pecahan sebagai gambar, garis bilangan dengan pecahan, pecahan senilai ditunjukkan secara visual, membandingkan dengan gambar
{n:21,type:"mcq",micro:"Membaca gambar lingkaran pecahan",q:"Sebuah gambar lingkaran diarsir sehingga 3 dari 5 bagian 'irisan pai' sama diwarnai. Pecahan apa yang diwakili gambar ini?",options:["2/5","3/5","5/3"],answer:1,explain:"3 bagian yang diarsir dari 5 total bagian sama mewakili pecahan 3/5.",hint:"Berapa total bagian sama yang digambarkan, dan berapa yang diarsir?"},
{n:22,type:"mcq",micro:"Gambar batang pecahan",q:"Sebuah batang pecahan dibagi menjadi 8 bagian sama, dengan 5 di antaranya diarsir. Pecahan apa yang diarsir?",options:["8/5","3/8","5/8"],answer:2,explain:"5 bagian diarsir dari 8 total bagian adalah pecahan 5/8.",hint:"Hitung total bagian dalam batang itu, lalu hitung berapa yang diarsir."},
{n:23,type:"mcq",micro:"Pecahan pada garis bilangan",q:"Sebuah garis bilangan dari 0 ke 1 dibagi menjadi 4 bagian sama. Pecahan apa yang berada pada tanda tepat 3 bagian dari 0?",options:["3/4","4/3","1/3"],answer:0,explain:"Berada pada 3 dari 4 bagian sama sepanjang jalan dari 0 ke 1 mewakili pecahan 3/4.",hint:"Jika garis dari 0 ke 1 dibagi menjadi 4 langkah sama, pecahan apa pada tanda langkah ke-3?"},
{n:24,type:"mcq",micro:"Pecahan senilai (piktorial)",q:"Sebuah gambar menunjukkan 1/2 dari sebuah batang diarsir, dan sebuah batang identik kedua dibagi menjadi 4 bagian sama dengan 2 diarsir. Apakah kedua gambar ini menunjukkan jumlah arsiran yang sama?",options:["Tidak, karena batangnya harus berbeda ukuran untuk dibandingkan","Ya, karena 1/2 dan 2/4 mewakili bagian arsiran yang persis sama dari batang identik","Tidak, karena 2/4 selalu lebih besar dari 1/2"],answer:1,explain:"1/2 dan 2/4 adalah pecahan senilai — keduanya mewakili jumlah yang persis sama, hanya dibagi menjadi jumlah bagian sama yang berbeda.",hint:"Jika kamu mengarsir tepat setengah dari sebuah batang, dan lalu membagi batang yang sama itu menjadi dua kali lebih banyak bagian sama, apakah ukuran sebenarnya dari bagian yang diarsir berubah?"},
{n:25,type:"order",micro:"Mengurutkan (membangun gambar pecahan)",q:"Urutkan langkah-langkah berikut untuk menggambar gambar yang menunjukkan pecahan 3/5.",items:["Arsir tepat 3 dari 5 bagian itu","Gambar sebuah batang dan bagi menjadi 5 bagian sama","Hitung bagian yang diarsir untuk memastikan ada 3"],answer:[1,0,2],explain:"Pertama bagi keseluruhan menjadi jumlah bagian sama yang tepat, lalu arsir jumlah yang benar dari bagian itu, lalu periksa kembali hitungannya.",hint:"Bisakah kamu mengarsir 3 bagian sebelum kamu bahkan membagi batangnya menjadi 5 bagian sama?"},
{n:26,type:"mcq",micro:"Membandingkan pecahan secara piktorial (penyebut sama)",q:"Gambar A menunjukkan 3/8 diarsir, Gambar B menunjukkan 5/8 diarsir (batang berukuran sama, jumlah total bagian sama). Gambar mana yang menunjukkan lebih banyak arsiran?",options:["Keduanya menunjukkan jumlah yang sama","Gambar A","Gambar B"],answer:2,explain:"Ketika penyebut (total bagian) sama, pecahan dengan pembilang (bagian yang diarsir) lebih besar mewakili lebih banyak — 5/8 lebih banyak dari 3/8.",hint:"Jika kedua batang dibagi menjadi jumlah bagian sama yang sama, pecahan mana yang memiliki lebih banyak bagian yang diarsir?"},
{n:27,type:"mcq",micro:"Membandingkan pecahan secara piktorial (pembilang sama)",q:"Gambar A menunjukkan 1/3 diarsir, Gambar B menunjukkan 1/6 diarsir (batang berukuran sama). Gambar mana yang menunjukkan lebih banyak arsiran?",options:["Gambar A (1/3)","Gambar B (1/6)","Keduanya menunjukkan jumlah yang sama"],answer:0,explain:"Ketika kamu membagi keseluruhan berukuran sama menjadi bagian yang lebih sedikit dan lebih besar (3 bagian) versus lebih banyak dan lebih kecil (6 bagian), 1 dari bagian yang lebih besar (1/3) lebih banyak daripada 1 dari bagian yang lebih kecil (1/6).",hint:"Jika batang yang sama dibagi menjadi hanya 3 potong versus 6 potong, apakah potongan individualnya lebih besar atau lebih kecil ketika jumlahnya lebih sedikit?"},
{n:28,type:"tf",micro:"Gambar sama, label berbeda",q:"Benar atau Salah: Sebuah gambar yang menunjukkan 2 dari 4 bagian sama diarsir mewakili jumlah arsiran yang persis sama dengan gambar yang menunjukkan 1 dari 2 bagian sama diarsir (pada keseluruhan berukuran identik).",answer:true,explain:"2/4 dan 1/2 adalah pecahan senilai yang mewakili bagian arsiran yang persis sama, hanya dibagi secara berbeda.",hint:"Apakah mengarsir '2 dari 4' mencakup area sebenarnya yang berbeda dari mengarsir '1 dari 2' pada keseluruhan berukuran sama?"},
{n:29,type:"mcq",micro:"Penempatan pecahan pada garis bilangan",q:"Pada garis bilangan dari 0 ke 1 yang dibagi menjadi 3 bagian sama, di mana pecahan 2/3 akan berada?",options:["Pada awal, tepat di 0","Pada tanda ke-2 dari 3 tanda sama, lebih dekat ke 1 daripada ke 0","Tepat di tengah pada 1/2"],answer:1,explain:"2/3 berada pada tanda pembagian ke-2 dari 3 tanda sama antara 0 dan 1, lebih dekat ke ujung 1.",hint:"Jika garis itu dibagi menjadi 3 langkah sama, di mana tanda langkah ke-2 jatuh?"},
{n:30,type:"mcq",micro:"Bilangan campuran secara piktorial",q:"Sebuah gambar menunjukkan 1 lingkaran utuh sepenuhnya diarsir, ditambah lingkaran kedua dengan 1 dari 4 bagian sama diarsir. Bilangan campuran apa yang diwakili ini?",options:["1 4/1","4 1/1","1 1/4"],answer:2,explain:"1 lingkaran utuh ditambah 1/4 dari lingkaran lain mewakili bilangan campuran 1 1/4 (satu dan satu-perempat).",hint:"Berapa lingkaran utuh yang sepenuhnya diarsir, dan pecahan ekstra apa yang diarsir di luar itu?"},
{n:31,type:"mcq",micro:"Model luas untuk pecahan",q:"Sebuah persegi panjang dibagi menjadi kisi 3 baris dan 4 kolom (total 12 persegi kecil sama), dengan 5 persegi diarsir. Berapa pecahan persegi panjang yang diarsir?",options:["5/12","12/5","7/12"],answer:0,explain:"5 persegi diarsir dari 12 total persegi sama adalah pecahan 5/12.",hint:"Berapa total persegi kecil sama yang membentuk keseluruhan persegi panjang itu, dan berapa yang diarsir?"},
{n:32,type:"classify",micro:"Mengelompokkan pecahan sebagai lebih atau kurang dari 1/2",q:"Kelompokkan setiap pecahan bergambar berdasarkan apakah itu mewakili lebih dari 1/2 atau kurang dari 1/2 dari keseluruhan berukuran sama.",items:["3/8 diarsir","5/8 diarsir","2/6 diarsir","4/6 diarsir"],groups:["Lebih dari 1/2","Kurang dari 1/2"],answer:{"Lebih dari 1/2":["5/8 diarsir","4/6 diarsir"],"Kurang dari 1/2":["3/8 diarsir","2/6 diarsir"]},explain:"5/8>1/2 (setengah dari 8 adalah 4, dan 5>4); 4/6>1/2 (setengah dari 6 adalah 3, dan 4>3); 3/8<1/2; 2/6<1/2.",hint:"Untuk setiap pecahan, bandingkan pembilangnya dengan setengah dari penyebutnya."},
{n:33,type:"mcq",micro:"Pecahan senilai digambarkan pada garis bilangan",q:"Pada garis bilangan, tanda untuk 1/2, 2/4, dan 3/6 semuanya jatuh pada titik yang persis sama. Apa yang ini beritahukan padamu?",options:["Garis bilangan digambar salah jika ini terjadi","1/2, 2/4, dan 3/6 semuanya pecahan senilai yang mewakili nilai yang sama","Ini kebetulan yang hanya berlaku untuk ketiga pecahan ini"],answer:1,explain:"Pecahan yang jatuh pada titik yang persis sama pada garis bilangan adalah senilai — mereka mewakili nilai yang sama, hanya ditulis dengan pembilang dan penyebut berbeda.",hint:"Jika pecahan berbeda semuanya menunjuk ke titik yang persis sama pada garis bilangan, apakah mereka mewakili jumlah yang berbeda atau jumlah yang sama?"},
{n:34,type:"mcq",micro:"Soal cerita piktorial",q:"Sebuah gambar resep menunjukkan gelas ukur terisi sampai tanda 3/4. Jika gelas penuh menampung total 4 bagian sama, berapa bagian cairan yang ditunjukkan?",options:["4","5","3"],answer:2,explain:"3/4 berarti 3 dari 4 bagian sama, jadi 3 bagian cairan ditunjukkan.",hint:"Pecahan 3/4 secara langsung memberitahumu berapa dari 4 bagian sama yang terisi."},
{n:35,type:"mcq",micro:"Membandingkan pecahan tidak sejenis secara piktorial",q:"Gambar A menunjukkan 2/3 diarsir, Gambar B menunjukkan 3/4 diarsir (batang berukuran sama). Menggunakan gambar itu, mana yang lebih besar?",options:["3/4","Keduanya sama","2/3"],answer:0,explain:"3/4 (yang hanya menyisakan 1/4 tidak diarsir, celah kecil) mencakup lebih banyak dari batang itu dibandingkan 2/3 (yang menyisakan 1/3 tidak diarsir, celah lebih besar).",hint:"Untuk setiap pecahan, pikirkan berapa banyak dari batang itu yang TIDAK DIARSIR — mana yang memiliki celah sisa lebih kecil?"},
{n:36,type:"tf",micro:"Estimasi piktorial dengan pecahan",q:"Benar atau Salah: Sebuah batang yang diarsir terlihat seperti 'hampir seluruh batang, tetapi dengan sedikit sisa tidak diarsir' kemungkinan besar mewakili pecahan yang dekat dengan 1, seperti 9/10, bukan pecahan seperti 1/2.",answer:true,explain:"Sebuah gambar dengan hanya sedikit sisa tidak diarsir mewakili pecahan yang sangat dekat dengan satu keseluruhan (seperti 9/10), karena hampir semua bagian diarsir.",hint:"Jika hampir seluruh batang diarsir kecuali sedikit sisa, apakah pecahan itu lebih dekat ke 1/2 atau lebih dekat ke 1 keseluruhan?"},
{n:37,type:"mcq",micro:"Menjembatani piktorial ke abstrak (menyederhanakan)",q:"Sebuah gambar menunjukkan batang dibagi menjadi 8 bagian sama dengan 4 diarsir (4/8). Dengan mengelompokkan ulang gambar itu menjadi bagian sama yang lebih sedikit dan lebih besar, pecahan senilai lebih sederhana apa yang bisa kamu lihat?",options:["2/8 (tidak ada pecahan lebih sederhana)","1/2","1/4"],answer:1,explain:"4/8 diarsir adalah jumlah yang sama dengan 1/2 diarsir — mengelompokkan ulang 8 bagian kecil menjadi 2 setengah sama yang lebih besar menunjukkan penyederhanaan ini secara visual.",hint:"Jika kamu mengelompokkan 8 bagian kecil menjadi pasangan, berapa bagian sama yang lebih besar yang akan kamu miliki, dan berapa dari itu yang akan diarsir?"},
{n:38,type:"mcq",micro:"Pecahan dari sekelompok benda (piktorial)",q:"Sebuah gambar menunjukkan 12 titik, dengan 8 di antaranya berwarna biru. Berapa pecahan titik yang berwarna biru, dan apakah ini bisa disederhanakan?",options:["8/12, yang disederhanakan menjadi 1/2","8/12, yang tidak bisa disederhanakan","8/12, yang disederhanakan menjadi 2/3"],answer:2,explain:"8/12 disederhanakan menjadi 2/3 (membagi angka atas dan bawah dengan faktor bersamanya, 4).",hint:"Apakah ada angka bersama yang habis membagi baik 8 maupun 12?"},
{n:39,type:"mcq",micro:"Pecahan tidak wajar secara piktorial",q:"Sebuah gambar menunjukkan 2 lingkaran utuh sepenuhnya diarsir, ditambah lingkaran ketiga dengan 1 dari 2 bagian diarsir. Sebagai pecahan tidak wajar (menggunakan setengahan), apa yang diwakili ini?",options:["5/2","2/5","3/2"],answer:0,explain:"2 lingkaran utuh (4 setengahan) ditambah 1 setengahan lagi memberikan total 5 setengahan, atau 5/2.",hint:"Berapa total bagian setengahan yang diarsir jika setiap lingkaran utuh dihitung sebagai 2 setengahan?"},
{n:40,type:"mcq",micro:"Memilih strategi gambar untuk perbandingan",q:"Untuk membandingkan 3/5 dan 5/8 menggunakan gambar, apa pendekatan yang membantu jika penyebutnya tidak cocok?",options:["Cukup bandingkan pembilangnya (3 vs 5) dan abaikan penyebutnya","Gambar ulang keduanya sebagai gambar dengan total jumlah bagian sama yang sama (penyebut yang sama) sehingga bisa dibandingkan secara langsung","Tidak mungkin membandingkan pecahan dengan penyebut berbeda menggunakan gambar"],answer:1,explain:"Menggambar ulang kedua pecahan menggunakan jumlah bagian sama yang dibagikan bersama (seperti perempatpuluhan) memungkinkan perbandingan piktorial langsung.",hint:"Akankah membandingkan dua gambar lebih mudah jika kedua batang dibagi menjadi jumlah bagian sama yang persis sama?"},

// PHASE C — ABSTRACT BRIDGING (41-60): notasi pecahan, menyederhanakan, penyebut sama, menjumlahkan/mengurangkan pecahan sejenis, membandingkan tanpa gambar
{n:41,type:"mcq",micro:"Menyederhanakan pecahan (abstrak)",q:"Sederhanakan 6/8 ke bentuk paling sederhana.",options:["2/3","6/8 (sudah paling sederhana)","3/4"],answer:2,explain:"6/8 disederhanakan menjadi 3/4 dengan membagi angka atas dan bawah dengan faktor bersamanya, 2.",hint:"Angka apa yang habis membagi baik 6 maupun 8?"},
{n:42,type:"mcq",micro:"Menyederhanakan pecahan (abstrak)",q:"Sederhanakan 10/15 ke bentuk paling sederhana.",options:["2/3","5/10","1/3"],answer:0,explain:"10/15 disederhanakan menjadi 2/3 dengan membagi angka atas dan bawah dengan faktor bersamanya, 5.",hint:"Angka apa yang habis membagi baik 10 maupun 15?"},
{n:43,type:"mcq",micro:"Menjumlahkan pecahan dengan penyebut sama",q:"1/5 + 2/5 = ?",options:["1/5","3/5","3/10"],answer:1,explain:"Ketika penyebutnya cocok, jumlahkan pembilangnya langsung: 1+2=3, tetap dengan penyebut yang sama: 3/5.",hint:"Karena kedua pecahan sudah memiliki penyebut yang sama, apa yang kamu lakukan dengan pembilangnya saja?"},
{n:44,type:"mcq",micro:"Mengurangkan pecahan dengan penyebut sama",q:"5/7 − 2/7 = ?",options:["3/14","7/7","3/7"],answer:2,explain:"Ketika penyebutnya cocok, kurangkan pembilangnya langsung: 5−2=3, tetap dengan penyebut yang sama: 3/7.",hint:"Karena kedua pecahan sudah memiliki penyebut yang sama, apa yang kamu lakukan dengan pembilangnya saja?"},
{n:45,type:"mcq",micro:"Menemukan penyebut sama",q:"Untuk menjumlahkan 1/3 + 1/4, penyebut sama apa yang bisa kamu gunakan?",options:["12","7","3"],answer:0,explain:"12 adalah kelipatan bersama dari 3 dan 4 (3×4=12), menjadikannya penyebut sama yang bisa digunakan.",hint:"Angka apa yang merupakan kelipatan dari 3 sekaligus kelipatan dari 4?"},
{n:46,type:"mcq",micro:"Menjumlahkan pecahan dengan penyebut berbeda",q:"1/3 + 1/4 = ?",options:["1/12","7/12","2/7"],answer:1,explain:"Mengonversi ke penyebut sama 12: 1/3=4/12 dan 1/4=3/12, jadi 4/12+3/12=7/12.",hint:"Konversikan kedua pecahan agar memiliki penyebut yang sama (seperti 12) sebelum menjumlahkan pembilangnya."},
{n:47,type:"mcq",micro:"Membandingkan pecahan secara abstrak",q:"Mana yang lebih besar: 3/5 atau 5/8?",options:["Keduanya sama","3/5","5/8"],answer:2,explain:"Mengonversi ke penyebut sama 40: 3/5=24/40 dan 5/8=25/40, jadi 5/8 lebih besar.",hint:"Konversikan kedua pecahan ke penyebut sama (seperti 40) dan bandingkan pembilangnya."},
{n:48,type:"order",micro:"Mengurutkan (menjumlahkan pecahan tidak sejenis)",q:"Urutkan langkah-langkah berikut untuk menyelesaikan 2/3 + 1/6.",items:["Jumlahkan pembilangnya: 4/6 + 1/6 = 5/6","Temukan penyebut sama (6 berhasil, karena 3×2=6)","Konversikan 2/3 menjadi perenaman: 2/3 = 4/6"],answer:[1,2,0],explain:"Pertama temukan penyebut sama, lalu konversikan setiap pecahan ke penyebut itu, lalu jumlahkan pembilangnya.",hint:"Bisakah kamu mengonversi 2/3 menjadi perenaman sebelum kamu memutuskan bahwa 6 adalah penyebut sama yang bisa digunakan?"},
{n:49,type:"mcq",micro:"Mengalikan pecahan dengan bilangan bulat",q:"3 × 1/4 = ?",options:["3/4","3/12","4/3"],answer:0,explain:"3 × 1/4 = 3/4 (mengalikan pecahan dengan bilangan bulat hanya mengalikan pembilangnya).",hint:"Jika kamu memiliki 3 kelompok berisi 1/4, berapa total perempatan yang kamu miliki?"},
{n:50,type:"classify",micro:"Sudah sederhana atau belum",q:"Kelompokkan setiap pecahan berdasarkan apakah sudah dalam bentuk paling sederhana atau masih bisa disederhanakan.",items:["4/9","6/10","5/7","8/12"],groups:["Sudah bentuk paling sederhana","Bisa disederhanakan"],answer:{"Sudah bentuk paling sederhana":["4/9","5/7"],"Bisa disederhanakan":["6/10","8/12"]},explain:"4/9 dan 5/7 tidak memiliki faktor bersama antara atas dan bawah selain 1; 6/10 disederhanakan menjadi 3/5, dan 8/12 disederhanakan menjadi 2/3.",hint:"Untuk setiap pecahan, periksa apakah ada angka lebih besar dari 1 yang habis membagi baik atas maupun bawah."},
{n:51,type:"mcq",micro:"Pecahan dari jumlah nyata",q:"Sebuah resep membutuhkan 3/4 dari kantong tepung seberat 200 gram. Berapa gram itu?",options:["100 gram","150 gram","175 gram"],answer:1,explain:"3/4 dari 200 = (200÷4)×3 = 50×3 = 150 gram.",hint:"Cari dulu berapa 1/4 dari 200, lalu kalikan dengan 3."},
{n:52,type:"mcq",micro:"Soal cerita pecahan (uang)",q:"Kamu punya Rp80.000 dan membelanjakan 1/4 untuk camilan. Berapa yang kamu belanjakan?",options:["Rp25.000","Rp15.000","Rp20.000"],answer:2,explain:"1/4 dari 80.000 = 80.000÷4 = 20.000.",hint:"Bagi total dengan penyebutnya (4) untuk menemukan satu-perempatnya."},
{n:53,type:"mcq",micro:"Mengonversi bilangan campuran ke pecahan tidak wajar",q:"Konversikan 2 1/3 menjadi pecahan tidak wajar.",options:["7/3","5/3","6/3"],answer:0,explain:"2 1/3 = (2×3+1)/3 = 7/3.",hint:"Kalikan bilangan bulat dengan penyebutnya, lalu tambahkan pembilangnya, tetap dengan penyebut yang sama."},
{n:54,type:"mcq",micro:"Mengonversi pecahan tidak wajar ke bilangan campuran",q:"Konversikan 11/4 menjadi bilangan campuran.",options:["3 3/4","2 3/4","2 1/4"],answer:1,explain:"11÷4=2 sisa 3, jadi 11/4 = 2 3/4.",hint:"Bagi pembilang dengan penyebutnya — hasil bilangan bulat dan sisanya membentuk bilangan campuran."},
{n:55,type:"mcq",micro:"Membandingkan pecahan menggunakan patokan 1/2",q:"Tanpa mencari penyebut sama, apakah 4/9 lebih besar atau lebih kecil dari 1/2?",options:["Lebih besar dari 1/2, karena 4 dan 9 keduanya lebih besar dari 2","Persis sama dengan 1/2","Lebih kecil dari 1/2, karena setengah dari 9 adalah 4,5, dan 4 lebih kecil dari 4,5"],answer:2,explain:"Setengah dari penyebutnya (9÷2=4,5) memberitahumu pembilang yang dibutuhkan agar tepat 1/2 — karena 4 lebih kecil dari 4,5, 4/9 sedikit di bawah 1/2.",hint:"Pembilang apa yang akan membuat pecahannya persis sama dengan 1/2, dengan penyebut 9?"},
{n:56,type:"mcq",micro:"Memeriksa jumlah pecahan dengan estimasi",q:"Kamu menghitung 3/8 + 1/2 dan mendapat 4/10. Menggunakan estimasi (3/8 sedikit kurang dari 1/2, jadi bersama dengan 1/2 lagi seharusnya mendekati 1), apa yang harus kamu curigai?",options:["Jawaban 4/10 kemungkinan salah, karena 4/10 kurang dari 1/2, padahal jumlah sebenarnya seharusnya mendekati 1","4/10 pasti benar karena itu pecahan yang valid","Estimasi tidak berlaku untuk penjumlahan pecahan"],answer:0,explain:"3/4+1/2 seharusnya mendekati 1 (jawaban benarnya 7/8), tetapi 4/10 kurang dari 1/2 — tanda bahwa pecahan itu tidak dikonversi ke penyebut sama dengan benar sebelum dijumlahkan.",hint:"Apakah 4/10 (kurang dari setengah) masuk akal sebagai jumlah dari dua pecahan yang masing-masing mendekati atau sama dengan setengah?"},
{n:57,type:"mcq",micro:"Mengurangkan pecahan dengan penyebut berbeda",q:"3/4 − 1/6 = ?",options:["5/12","7/12","2/12"],answer:1,explain:"Mengonversi ke penyebut sama 12: 3/4=9/12 dan 1/6=2/12, jadi 9/12−2/12=7/12.",hint:"Konversikan kedua pecahan ke penyebut sama (seperti 12) sebelum mengurangkan."},
{n:58,type:"mcq",micro:"Kaitan pecahan dan pembagian",q:"Apa lagi yang diwakili pecahan 3/4, dalam bentuk pembagian?",options:["4 dibagi 3","3 dikalikan 4","3 dibagi 4"],answer:2,explain:"Sebuah pecahan secara harfiah adalah pembagian: 3/4 berarti 3÷4, mewakili 3 keseluruhan dibagi rata di antara 4.",hint:"Bisakah 'membagi 3 pizza secara rata di antara 4 orang' menggambarkan baik soal pembagian maupun pecahan 3/4?"},
{n:59,type:"mcq",micro:"Membandingkan jumlah pecahan",q:"Jumlah mana yang lebih besar: 1/2 + 1/3, atau 2/3 + 1/6?",options:["Keduanya sama","1/2 + 1/3","2/3 + 1/6"],answer:0,explain:"1/2+1/3=3/6+2/6=5/6; 2/3+1/6=4/6+1/6=5/6 — kedua jumlah sama dengan 5/6, jadi keduanya sama.",hint:"Konversikan setiap pasangan ke penyebut sama (seperti perenaman) dan jumlahkan sebelum membandingkan."},
{n:60,type:"mcq",micro:"Memilih operasi yang tepat",q:"Sebuah soal mengatakan: 'Sebuah pita panjangnya 3/4 meter. Sepotong sepanjang 1/4 meter dipotong. Berapa panjang pita yang tersisa?' Operasi apa yang menyelesaikan ini?",options:["Perkalian, karena melibatkan pengukuran","Pengurangan, karena sepotong dihilangkan dari total panjang","Penjumlahan, karena dua pecahan diberikan"],answer:1,explain:"Menghilangkan sepotong dari total panjang adalah situasi pengurangan, bahkan ketika jumlahnya berupa pecahan: 3/4−1/4=2/4=1/2.",hint:"Apakah panjang pita bertambah atau berkurang setelah potongannya dipotong?"},

// PHASE D — REASONING (61-80): mengapa aturan pecahan berlaku, analisis kesalahan, perbandingan strategi, penalaran pecahan dunia nyata
{n:61,type:"mcq",micro:"Mengapa kamu tidak bisa langsung menjumlahkan pecahan dengan penyebut berbeda",q:"Mengapa kamu tidak bisa langsung menjumlahkan pembilang dan penyebut untuk 1/2 + 1/3 (mendapat 2/5)?",options:["Karena aturan penjumlahan pecahan hanya sembarangan tanpa alasan nyata","Karena 2/5 sebenarnya jawaban yang benar, dan kekhawatiran ini tidak berdasar","Karena 1/2 dan 1/3 mewakili bagian dari keseluruhan yang dibagi menjadi ukuran potongan berbeda, jadi pembilangnya tidak bisa langsung digabungkan tanpa dulu menyamakan ukuran potongannya"],answer:2,explain:"Setengahan dan sepertigaan adalah potongan berukuran berbeda — kamu harus mengonversi ke ukuran potongan yang dibagikan bersama (penyebut sama) sebelum pembilangnya bisa digabungkan secara bermakna.",hint:"Apakah 'potongan' dalam 1/2 dan 'potongan' dalam 1/3 berukuran sama, dan apakah itu penting untuk menjumlahkannya langsung?"},
{n:62,type:"open",micro:"Analisis kesalahan",q:"Seorang siswa menyelesaikan 2/3 + 1/3 dan menulis 3/6. Temukan kemungkinan kesalahannya dan jelaskan cara memperbaikinya.",sample:"2/3+1/3=3/3=1, bukan 3/6 — siswa itu kemungkinan menjumlahkan baik pembilang MAUPUN penyebutnya (2+1=3, 3+3=6) alih-alih hanya menjumlahkan pembilangnya dan mempertahankan penyebut yang sama; meninjau bahwa penjumlahan penyebut sama hanya menggabungkan pembilangnya akan memperbaiki ini.",explain:"Menjumlahkan penyebut bersama-sama (alih-alih mempertahankannya tetap sama) adalah salah satu kesalahan penjumlahan pecahan yang paling umum.",hint:"Ketika penyebutnya sudah cocok, haruskah penyebutnya sendiri berubah saat kamu menjumlahkan?"},
{n:63,type:"open",micro:"Estimasi vs penalaran tepat",q:"Kapan perkiraan cepat yang melibatkan pecahan (seperti 'kira-kira setengah') sudah cukup baik, dan kapan kamu membutuhkan pecahan yang tepat? Berikan satu contoh nyata masing-masing.",sample:"Perkiraan sudah cukup untuk hal seperti menebak kira-kira berapa banyak pizza yang tersisa setelah pesta ('sekitar sepertiga tersisa'); pecahan yang tepat penting untuk hal seperti resep yang membutuhkan tepat 3/4 cangkir bahan, di mana menggunakan 'sekitar 3/4' secara longgar bisa mengubah hasilnya secara nyata.",explain:"Mengenali kapan presisi pecahan benar-benar penting versus kapan perkiraan yang masuk akal sudah cukup mencerminkan number sense yang matang.",hint:"Pikirkan situasi di mana meleset 'sedikit pecahan' tidak masalah, dibandingkan dengan situasi di mana itu benar-benar masalah."},
{n:64,type:"mcq",micro:"Mengapa pecahan senilai berlaku",q:"Mengapa mengalikan pembilang dan penyebut suatu pecahan dengan angka yang sama (seperti mengubah 1/2 menjadi 2/4) tidak mengubah nilainya?",options:["Karena mengalikan kedua bagian dengan angka yang sama sama dengan mengalikan seluruh pecahan dengan 1 (seperti 2/2), yang tidak pernah mengubah suatu nilai","Karena itu aturan khusus yang hanya berlaku untuk angka 2","Karena pecahan senilai sebenarnya nilai berbeda yang hanya terlihat mirip"],answer:0,explain:"Mengalikan atas dan bawah dengan angka yang sama setara dengan mengalikan dengan suatu bentuk 1 (seperti 2/2 atau 3/3), dan mengalikan apa pun dengan 1 tidak pernah mengubah nilainya.",hint:"Apakah mengalikan sebuah pecahan dengan 2/2 sama dengan mengalikannya dengan 1?"},
{n:65,type:"open",micro:"Penalaran dunia nyata",q:"Sebuah resep sedang diskalakan dari menyajikan 4 orang menjadi menyajikan 6 orang, membutuhkan setiap jumlah bahan pecahan dikalikan dengan 6/4 (atau 3/2). Mengapa memahami pecahan penting untuk ini, alih-alih hanya menebak?",sample:"Tanpa mengalikan setiap jumlah bahan pecahan (seperti 3/4 cangkir atau 1/3 sendok teh) dengan pecahan penskalaan yang persis sama, proporsi resep akan kacau, berpotensi merusak rasa atau teksturnya — perkalian pecahan yang tepat menjamin setiap bahan diskalakan secara konsisten dan benar.",explain:"Ini mencerminkan kebutuhan nyata akan kefasihan pecahan di luar sekadar soal buku teks.",hint:"Jika kamu menebak jumlah bahan baru alih-alih menghitungnya dengan tepat, apakah proporsi resep kemungkinan tetap seimbang?"},
{n:66,type:"mcq",micro:"Memilih strategi yang efisien",q:"Untuk membandingkan 7/8 dan 9/10, strategi mana yang paling cepat?",options:["Tidak ada cara yang lebih cepat daripada menggambar keduanya sebagai gambar","Bandingkan seberapa jauh setiap pecahan dari 1 keseluruhan (jarak 1/8 vs jarak 1/10) — yang lebih dekat ke 1 lebih besar","Hanya menemukan penyebut sama penuh yang berhasil di sini"],answer:1,explain:"Karena kedua pecahan dekat dengan 1, membandingkan 'jarak dari 1' masing-masing (1/8 vs 1/10) jauh lebih cepat daripada mencari penyebut sama penuh — karena 1/10 celahnya lebih kecil dari 1/8, 9/10 lebih dekat ke 1 dan karenanya lebih besar.",hint:"Seberapa jauh setiap pecahan dari satu keseluruhan (1), dan celah mana yang lebih kecil?"},
{n:67,type:"open",micro:"Menyelidiki perbedaan hasil",q:"Dua orang secara terpisah menghitung 3/4 − 1/6 dan mendapat 7/12 dan 5/12. Jelaskan rencana langkah demi langkah untuk menemukan jawaban yang benar.",sample:"Hitung ulang dengan hati-hati menggunakan penyebut sama yang jelas: 3/4=9/12 dan 1/6=2/12, jadi 9/12−2/12=7/12 — mengonfirmasi 7/12 benar, dan menunjukkan percobaan lain kemungkinan membuat kesalahan baik saat mengonversi 1/6 menjadi perduabelasan maupun saat mengurangkan pembilangnya.",explain:"Dengan hati-hati mengulangi langkah konversi-ke-penyebut-sama, dan memeriksa setiap bagian, adalah cara andal menyelesaikan perbedaan pengurangan pecahan.",hint:"Bisakah mengulangi konversi kedua pecahan ke penyebut sama (perduabelasan) langkah demi langkah membantu menemukan tepat di mana satu percobaan salah?"},
{n:68,type:"mcq",micro:"Ketika mental math mungkin gagal",q:"Untuk menjumlahkan beberapa pecahan dengan penyebut yang sangat berbeda dan 'tidak ramah' (seperti 1/7 + 1/11 + 1/13), mengapa metode tertulis mungkin lebih aman daripada mental math murni?",options:["Karena mental math tidak pernah berhasil untuk soal pecahan apa pun","Karena kalkulator selalu memberikan jawaban salah untuk pecahan","Karena menemukan dan melacak penyebut sama yang tidak ramah (seperti 1001) jauh lebih andal secara tertulis daripada murni di kepala"],answer:2,explain:"Penyebut sama yang tidak ramah dan besar sulit ditemukan dan dilacak secara mental, membuat pendekatan tertulis jauh lebih aman untuk soal jenis ini.",hint:"Seberapa mudah menemukan dan melacak penyebut sama seperti 1001 murni di kepala?"},
{n:69,type:"open",micro:"Menerapkan pecahan pada keadilan",q:"Tiga teman membagi sebuah pizza, tetapi satu teman jauh lebih lapar dan memakan 1/2, sementara dua lainnya membagi sisanya secara rata. Jelaskan, menggunakan pecahan, berapa yang didapat masing-masing dari dua teman lainnya, dan apakah ini terasa adil.",sample:"Jika 1/2 dimakan oleh teman pertama, 1/2 tersisa, dibagi rata di antara dua lainnya: (1/2)÷2 = 1/4 masing-masing — jadi pembagiannya adalah 1/2, 1/4, 1/4; apakah ini terasa 'adil' tergantung pada apakah semua orang benar-benar setuju sebelumnya, karena ini bukan pembagian tiga arah yang sama rata.",explain:"Menghubungkan pembagian pecahan dan penalaran langsung dengan diskusi keadilan nyata, menunjukkan matematika dan keadilan tidak selalu sama.",hint:"Setelah teman pertama memakan 1/2, berapa pizza yang tersisa untuk dibagi antara dua teman yang tersisa?"},
{n:70,type:"mcq",micro:"Kaitan pecahan dan nilai tempat/desimal",q:"Mengapa pecahan 1/2 berhubungan langsung dengan desimal 0,5?",options:["Karena 1/2 berarti 1 dibagi 2, dan menghitung pembagian itu memberikan tepat 0,5","Karena desimal dan pecahan adalah sistem angka yang sama sekali tidak berhubungan","Karena 0,5 hanya berfungsi sebagai perkiraan untuk 1/2, tidak pernah kecocokan tepat"],answer:0,explain:"Setiap pecahan secara harfiah adalah soal pembagian, dan membagi 1 dengan 2 memberikan tepat 0,5 — pecahan dan desimal adalah dua cara berbeda untuk menulis nilai yang sama.",hint:"Jika kamu benar-benar melakukan pembagian 1÷2, angka desimal apa yang kamu dapat?"},
{n:71,type:"open",micro:"Penalaran estimasi kehidupan nyata",q:"Sebelum menghitung secara tepat, bagaimana estimasi cepat (menggunakan pecahan patokan seperti 1/2, 1/4, 3/4) bisa membantumu merasakan kira-kira berapa sisa anggaran Rp500.000 setelah membelanjakan 'kira-kira 2/3' dari itu?",sample:"Menyadari 2/3 sedikit lebih dari 1/2, kamu bisa cepat merasakan bahwa sedikit kurang dari setengah anggaran (sedikit kurang dari Rp250.000) tersisa, memberimu pemeriksaan naluri yang cepat dan berguna sebelum menghitung jumlah sisa yang tepat (yaitu 500.000×1/3≈166.667).",explain:"Ini adalah penggunaan praktis nyata dari estimasi pecahan patokan untuk pemeriksaan naluri anggaran cepat.",hint:"Apakah 2/3 lebih dekat ke 1/2 atau lebih dekat ke satu keseluruhan, dan apa yang disarankan itu tentang berapa banyak yang tersisa setelah membelanjakannya?"},
{n:72,type:"mcq",micro:"Mengenali pola dalam urutan pecahan",q:"1/2, 1/4, 1/8, 1/16 — pola apa yang kamu perhatikan saat urutan ini berlanjut?",options:["Sama sekali tidak ada pola","Setiap pecahan adalah setengah dari yang sebelumnya","Setiap pecahan adalah dua kali dari yang sebelumnya"],answer:1,explain:"Setiap pecahan dalam urutan ini tepat setengah ukuran dari yang sebelumnya (membagi kedua bagian dengan 2 setiap kali, atau setara dengan menggandakan penyebutnya).",hint:"Bandingkan setiap pecahan dengan yang tepat sebelumnya — apakah lebih besar, lebih kecil, atau sama?"},
{n:73,type:"open",micro:"Refleksi pilihan strategi",q:"Jelaskan soal pecahan nyata di mana kamu akan menggunakan perkiraan pecahan patokan (seperti 'mendekati 1/2') alih-alih perhitungan tepat, dan satu di mana kamu akan membutuhkan perhitungan pecahan tepat.",sample:"Untuk hal seperti cepat menilai apakah 'sekitar 4/9 dari kelas' kira-kira setengah (cukup dekat dengan 1/2 untuk penghitungan kepala kelas yang cepat), perkiraan patokan sudah cukup; tetapi untuk hal seperti pengukuran konstruksi yang membutuhkan tepat 5/8 inci, perhitungan pecahan tepat sangat penting karena bahkan kesalahan pecahan kecil bisa menyebabkan ketidakcocokan fisik nyata.",explain:"Mengenali bahwa estimasi berhasil untuk penilaian kasar sementara perhitungan tepat penting untuk kebutuhan dunia nyata yang presisi menunjukkan penilaian strategis yang nyata.",hint:"Apakah situasi seperti pengukuran konstruksi mentoleransi pecahan yang 'kira-kira dekat' sama seperti penghitungan kepala kelas yang kasar?"},
{n:74,type:"mcq",micro:"Menafsirkan pecahan perkiraan",q:"Sebuah laporan mengatakan 'kira-kira 3/4 dari responden survei' lebih memilih suatu pilihan. Apa yang disarankan 'kira-kira' tentang pecahan tepatnya?",options:["Pecahan tepatnya persis 3/4, tanpa pembulatan yang terlibat","Tidak ada hubungan nyata antara 'kira-kira' dan pecahan sebenarnya","Pecahan tepatnya dekat dengan tetapi belum tentu persis 3/4"],answer:2,explain:"'Kira-kira' menandakan pecahan sebenarnya dekat dengan tetapi kemungkinan bukan 3/4 yang persis dan bulat sempurna.",hint:"Apakah 'kira-kira 3/4' menjanjikan pecahan yang tepat, atau hanya kedekatan yang masuk akal dengannya?"},
{n:75,type:"open",micro:"Pecahan di bawah tekanan",q:"Saat permainan kelas yang cepat di mana siswa harus cepat membandingkan dua pecahan yang ditunjukkan pada kartu, kebiasaan apa yang membantu menghindari kesalahan ceroboh bahkan saat terburu-buru?",sample:"Cepat memeriksa pecahan patokan (seperti membandingkan setiap pecahan dengan 1/2 dulu) alih-alih selalu terburu-buru mencari penyebut sama penuh membantu, karena banyak perbandingan bisa diselesaikan lebih cepat dan sama akuratnya menggunakan pemeriksaan patokan cepat.",explain:"Kebiasaan perbandingan-patokan yang spesifik dan cepat menyeimbangkan kecepatan dan akurasi di bawah tekanan.",hint:"Akankah membandingkan setiap pecahan dengan patokan sederhana seperti 1/2 kadang membuatmu bisa melewati langkah lebih lambat mencari penyebut sama penuh?"},
{n:76,type:"mcq",micro:"Kaitan pecahan dan probabilitas",q:"Jika sebuah tas berisi 3 kelereng merah dan 7 kelereng biru (total 10), bagaimana pecahan 3/10 berhubungan dengan peluang mengambil kelereng merah?",options:["3/10 secara langsung mewakili probabilitas (kemungkinan) mengambil kelereng merah dalam satu pengambilan acak","3/10 sama sekali tidak berhubungan dengan probabilitas","3/10 hanya berlaku jika kamu mengambil kelereng dalam urutan tertentu"],answer:0,explain:"Probabilitas pada dasarnya adalah pecahan: jumlah hasil yang diinginkan (3 merah) dari total kemungkinan hasil (10 kelereng) secara langsung memberikan probabilitas, 3/10.",hint:"Apakah 'bagian dari keseluruhan' menggambarkan baik pecahan maupun probabilitas dasar pada saat yang sama?"},
{n:77,type:"open",micro:"Menjelaskan strategi ke orang lain",q:"Seorang siswa yang lebih muda selalu membandingkan pecahan hanya dengan melihat pembilang atau penyebut mana yang lebih besar, tanpa mempertimbangkan keduanya bersama. Apa yang akan kamu ajarkan padanya sebagai gantinya, dan mengapa itu membantu?",sample:"Saya akan mengajarkan mereka untuk selalu mencari penyebut sama dulu (atau menggunakan patokan seperti 1/2) sebelum membandingkan, karena hanya melihat pembilang atau hanya penyebut saja bisa menyesatkan — misalnya, 1/2 memiliki pembilang lebih kecil daripada yang mungkin disarankan hubungan penyebut 1/3, tetapi 1/2 sebenarnya lebih besar dari 1/3.",explain:"Mengajarkan metode perbandingan pecahan yang tepat alih-alih perbandingan digit yang dangkal mencerminkan pemahaman nyata tentang mengapa pecahan bekerja seperti itu.",hint:"Akankah hanya membandingkan '2' dan '3' secara langsung (mengabaikan apa yang mereka wakili sebagai penyebut) dengan benar memberitahumu apakah 1/2 atau 1/3 yang lebih besar?"},
{n:78,type:"mcq",micro:"Mengenali hasil yang tidak mungkin",q:"Kamu diberitahu bahwa menjumlahkan dua pecahan wajar (masing-masing kurang dari 1) memberikan hasil 3.",options:["Pecahan tidak pernah bisa dijumlahkan sama sekali","Kemungkinan besar terjadi kesalahan, karena menjumlahkan dua pecahan yang masing-masing kurang dari 1 paling banyak memberikan hasil sedikit kurang dari 2","Ini sepenuhnya normal dan diharapkan"],answer:1,explain:"Jumlah terbesar yang mungkin dari dua pecahan yang masing-masing kurang dari 1 adalah sedikit kurang dari 1+1=2, jadi hasil 3 menandakan kesalahan aritmetika.",hint:"Berapa jumlah terbesar yang mungkin jika kedua pecahan yang dijumlahkan masing-masing kurang dari 1?"},
{n:79,type:"open",micro:"Merancang sistem berbagi berbasis pecahan yang adil",q:"Rancang cara sederhana bagi 3 teman untuk membagi secara adil sekelompok tugas yang tidak terbagi rata menjadi tugas utuh (seperti 10 pekerjaan rumah di antara 3 orang), menggunakan pemikiran pecahan.",sample:"Membagi 10 pekerjaan dengan 3 orang memberikan 3 1/3 pekerjaan masing-masing — karena kamu tidak bisa benar-benar mengerjakan 1/3 dari kebanyakan pekerjaan, sepakati bahwa 2 orang mengerjakan 3 pekerjaan masing-masing dan 1 orang mengerjakan 4 pekerjaan (memperhitungkan sisa pecahan 1/3), dan bergiliran siapa yang mendapat pekerjaan ekstra setiap kali untuk menjaga keadilan dalam jangka panjang.",explain:"Menghubungkan pembagian pecahan (termasuk menangani sisa pecahan secara praktis) dengan sistem berbagi tugas yang adil dan nyata.",hint:"Karena 10÷3 tidak habis dibagi, bagaimana sistem yang adil bisa menangani bagian pecahan sisa secara praktis, seiring waktu?"},
{n:80,type:"mcq",micro:"Pemeriksaan keyakinan pecahan",q:"Kamu menghitung 5/6 − 1/3 tiga kali terpisah dan mendapat 1/2, 1/2, dan 2/3. Apa kesimpulan yang paling masuk akal?",options:["Selisih sebenarnya pasti 2/3, karena memiliki penyebut lebih besar","Tidak ada dari ketiga percobaan yang bisa dipercaya","Selisih sebenarnya sangat mungkin 1/2, karena cocok dengan dua dari tiga percobaan"],answer:2,explain:"Ketika sebagian besar percobaan berulang cocok (dua dari tiga mendapat 1/2), nilai itu adalah hasil yang lebih bisa dipercaya.",hint:"Jawaban mana yang muncul lebih sering di antara ketiga percobaanmu — 1/2 atau 2/3?"},

// PHASE E — CHALLENGE (81-100): kapstone, masalah nyata multi-langkah, investigasi, refleksi
{n:81,type:"open",micro:"Masalah nyata multi-langkah",q:"Sebuah resep untuk 4 orang membutuhkan 2/3 cangkir gula. Kamu ingin membuat cukup untuk 6 orang. Berapa gula yang kamu butuhkan, dan bagaimana kamu menemukannya?",sample:"Faktor skala adalah 6/4=3/2, jadi kalikan 2/3 × 3/2 = 6/6 = 1 cangkir gula dibutuhkan — ditemukan dengan pertama menemukan pecahan skala yang tepat, lalu mengalikannya dengan jumlah aslinya.",explain:"Penerapan langsung perkalian pecahan pada skenario penskalaan resep nyata.",hint:"Pecahan skala apa yang membawamu dari menyajikan 4 orang ke menyajikan 6 orang, dan bagaimana kamu menerapkannya pada jumlah gula?"},
{n:82,type:"open",micro:"Merancang rencana anggaran berbasis pecahan",q:"Kamu berencana membelanjakan 1/2 dari uang saku Rp600.000-mu untuk tabungan, 1/4 untuk kebutuhan, dan sisanya untuk kegiatan seru. Jelaskan bagaimana kamu akan menggunakan pecahan untuk mengetahui persis berapa yang masuk ke setiap kategori.",sample:"Tabungan: 1/2×600.000=300.000; kebutuhan: 1/4×600.000=150.000; kegiatan seru mendapat pecahan apa pun yang tersisa (1−1/2−1/4=1/4), yang juga 1/4×600.000=150.000 — ditemukan dengan menghitung jumlah setiap pecahan bernama, lalu mencari tahu pecahan sisa untuk kategori terakhir.",explain:"Menerapkan penganggaran berbasis pecahan nyata langsung pada keputusan alokasi yang sungguhan.",hint:"Setelah memperhitungkan pecahan tabungan dan kebutuhan, pecahan apa dari keseluruhan yang tersisa untuk kegiatan seru?"},
{n:83,type:"open",micro:"Menyelidiki klaim pecahan yang tidak konsisten",q:"Sebuah kartu resep mengklaim sebuah hidangan menggunakan 'total 3/4 cangkir cairan,' tetapi ketika kamu benar-benar menjumlahkan bahan cairan yang tercantum (1/2 cangkir + 1/3 cangkir), pecahannya tampak tidak cocok. Bagaimana kamu akan menyelidiki ini dengan jujur?",sample:"Benar-benar jumlahkan jumlah cairan yang tercantum dengan hati-hati menggunakan penyebut sama: 1/2+1/3 = 3/6+2/6 = 5/6 cangkir, yang tidak cocok dengan klaim 3/4 cangkir — ini menandakan mungkin ada kesalahan cetak pada kartu resep, atau ada bahan cairan yang tidak terhitung, patut diperiksa ulang terhadap sumber resep aslinya.",explain:"Mengenali dan dengan jujur menyelidiki perbedaan nyata antara total pecahan yang dinyatakan dan perhitungan pecahan sebenarnya mencerminkan penalaran matang tentang pecahan dalam konteks nyata.",hint:"Apakah benar-benar menjumlahkan pecahan cairan yang tercantum memberikan total yang sama dengan klaim kartu resep itu?"},
{n:84,type:"open",micro:"Koneksi sejarah/budaya",q:"Cari tahu (atau ingat kembali) satu penggunaan pecahan sejarah atau budaya nyata (seperti pecahan satuan Mesir kuno, sistem pengukuran tradisional, atau notasi irama musik). Jelaskan singkat bagaimana pecahan digunakan.",sample:"Matematika Mesir kuno terkenal menggunakan 'pecahan satuan' (pecahan dengan pembilang 1, seperti 1/3 atau 1/7) hampir secara eksklusif, menyatakan pecahan lain sebagai jumlah dari pecahan satuan yang berbeda — ini menunjukkan pecahan sudah penting untuk pengukuran dan perhitungan yang tepat di berbagai budaya dan zaman, bukan hanya kelas modern.",explain:"Menghubungkan konsep pecahan dengan praktik sejarah dan budaya menunjukkan relevansi skill ini yang lebih luas di dunia nyata dan sejarah.",hint:"Mengapa pengukuran pecahan yang tepat mungkin penting dalam perdagangan, konstruksi, atau pencatatan kuno?"},
{n:85,type:"open",micro:"Masalah tabungan multi-langkah dengan pecahan",q:"Kamu menabung 1/5 dari uang saku bulananmu setiap bulan. Jika uang sakumu Rp250.000 per bulan, berapa total yang akan kamu tabung setelah 4 bulan, dan bagaimana kamu menemukannya?",sample:"1/5 dari 250.000 = 50.000 ditabung per bulan, lalu selama 4 bulan: 50.000×4=200.000 total ditabung — ditemukan dengan pertama mencari jumlah bulanan menggunakan pecahan, lalu mengalikannya dengan jumlah bulan.",explain:"Menerapkan perhitungan pecahan-dari-suatu-jumlah dikombinasikan dengan perkalian pada skenario tabungan nyata.",hint:"Cari dulu berapa yang ditabung dalam satu bulan menggunakan pecahan itu, lalu kalikan dengan jumlah bulan."},
{n:86,type:"open",micro:"Refleksi kesalahan pecahan",q:"Ceritakan saat nyata (dalam skill ini atau dalam kehidupan nyata) ketika kamu membuat kesalahan dengan pecahan. Apa penyebab kesalahannya, dan apa yang akan kamu lakukan berbeda sekarang?",sample:"Bersifat personal dan terbuka — tujuannya adalah mengenali penyebab nyata (seperti menjumlahkan penyebut bersama-sama alih-alih mencari penyebut sama, lupa menyederhanakan, atau salah membaca angka mana yang pembilang versus penyebut) dan menyebutkan perbaikan konkret, seperti selalu memeriksa ulang dengan gambar atau perkiraan.",explain:"Merenungkan kesalahan pecahan pribadi yang nyata, dengan perbaikan konkret, menunjukkan skill ini sudah benar-benar tertanam.",hint:"Ingat kembali momen ketika jawaban pecahanmu ternyata salah — apa tepatnya yang salah dalam langkahmu?"},
{n:87,type:"open",micro:"Merancang sistem berbagi pecahan di kelas",q:"Rancang sistem sederhana bagi kelas berisi 24 siswa untuk membagi rata sekelompok tugas atau perlengkapan menggunakan pemikiran pecahan, ketika angkanya tidak terbagi rata.",sample:"Jika membagi 24 siswa ke dalam kelompok kecil di mana setiap kelompok seharusnya mendapat 1/6 dari sekumpulan perlengkapan bersama, hitung 1/6 dari total jumlah perlengkapan per kelompok, dan jika ada barang yang tersisa (sisa pecahan), bergiliran kelompok mana yang menerima barang ekstra setiap kali tugas serupa muncul, menjaga sistem tetap adil dalam jangka panjang.",explain:"Ini adalah sistem praktis berbasis pecahan untuk membagi sumber daya kelas nyata secara andal dan adil.",hint:"Akankah bergiliran siapa yang menerima sisa pecahan kecil apa pun, alih-alih selalu memberikannya ke kelompok yang sama, membantu menjaga keadilan seiring waktu?"},
{n:88,type:"open",micro:"Memperkirakan dan memverifikasi dengan pecahan",q:"Perkirakan kira-kira berapa pecahan dari film berdurasi 2 jam yang telah diputar setelah 50 menit, lalu jelaskan bagaimana kamu akan memverifikasi perkiraanmu.",sample:"50 menit dari 120 menit dekat dengan 1/2 jam dari 2 jam, jadi kira-kira sedikit kurang dari setengah film (mendekati 5/12, karena 50/120 disederhanakan) telah diputar — kamu bisa memverifikasi dengan menyederhanakan tepat 50/120 (membagi keduanya dengan 10 untuk mendapat 5/12) dan memeriksa apakah itu cukup dekat dengan perkiraan patokanmu.",explain:"Ini menerapkan teknik 'perkiraan pecahan patokan dulu, lalu verifikasi dengan penyederhanaan tepat' pada skenario sehari-hari yang nyata.",hint:"Apakah 50 menit lebih dekat dengan sepertiga, setengah, atau hampir seluruh film berdurasi 120 menit itu?"},
{n:89,type:"open",micro:"Menyelidiki perbedaan nyata (penskalaan bahan)",q:"Sebuah toko roti menskalakan resep dengan perkiraan menggunakan 3/4 kg tepung (berdasarkan menskalakan resep asli 1/2 kg dengan 3/2), tetapi sebenarnya menggunakan 4/5 kg. Berikan dua kemungkinan penjelasan berbeda, dan bagaimana kamu akan menyelidiki masing-masing.",sample:"Kemungkinan 1: perhitungan penskalaan itu sendiri memiliki kesalahan — periksa ulang apakah 1/2 kg × 3/2 benar-benar sama dengan 3/4 kg (memang benar, jadi ini perlu memeriksa ulang faktor skala yang benar-benar digunakan). Kemungkinan 2: tepung ekstra digunakan dalam praktiknya karena alasan di luar resep (seperti menaburi meja atau pengukuran yang sedikit berlebih) — periksa dengan pembuat roti sebenarnya tentang praktik dapur nyata versus penskalaan resep teoretis.",explain:"Mempertimbangkan beberapa penyebab yang mungkin untuk perbedaan berbasis pecahan dunia nyata, dan cara mengujinya, mencerminkan penalaran investigatif yang nyata tentang jumlah yang diskalakan.",hint:"Bisakah kesenjangan itu berasal dari kesalahan dalam perhitungan penskalaan itu sendiri, atau dari penggunaan tepung praktis nyata di luar matematika resep yang tepat?"},
{n:90,type:"open",micro:"Kaitan pecahan dan statistik",q:"Sebuah survei menunjukkan 18 dari 24 siswa lebih memilih pilihan makan siang tertentu. Bagaimana menyatakan ini sebagai pecahan 18/24 (disederhanakan menjadi 3/4) membantumu mengkomunikasikan dan menalar hasilnya?",sample:"Menyederhanakan 18/24 menjadi 3/4 membuat hasilnya jauh lebih mudah dipahami dan dikomunikasikan sekilas ('tiga perempat siswa lebih memilih pilihan ini') dibandingkan dengan angka mentah, dan juga memudahkan perbandingan dengan survei lain dari total ukuran berbeda yang mungkin melaporkan pecahan serupa.",explain:"Ini menghubungkan penyederhanaan pecahan langsung dengan komunikasi statistik yang lebih jelas dan perbandingan di seluruh kelompok berukuran berbeda.",hint:"Apakah 'tiga perempat siswa' atau '18 dari 24 siswa' lebih mudah untuk cepat dipahami dan dibandingkan dengan survei lain?"},
{n:91,type:"open",micro:"Mini proyek",q:"Rancang dan hitung skenario berbasis pecahan nyata (seperti menskalakan resep, membagi anggaran, atau membagi sumber daya bersama), menunjukkan pekerjaan pecahanmu dengan jelas. Laporkan hasil dan metodemu.",sample:"Bersifat personal dan terbuka — tujuannya adalah mempraktikkan operasi pecahan nyata (menyederhanakan, membandingkan, menjumlahkan/mengurangkan, atau mengalikan pecahan) dalam skenario realistis yang kamu rancang sendiri.",explain:"Ini adalah penerapan kapstone langsung dari skill pecahan pada tugas nyata yang kamu rancang sendiri.",hint:"Akankah menunjukkan setiap langkah pecahan dengan jelas (seperti menemukan penyebut sama, atau menyederhanakan jawaban akhirmu) membuat pekerjaanmu lebih mudah diperiksa dan dipercaya?"},
{n:92,type:"open",micro:"Menjelaskan pecahan ke anak yang jauh lebih muda",q:"Bagaimana kamu akan menjelaskan arti pecahan seperti 1/4 kepada anak yang belum pernah melihatnya, menggunakan sesuatu yang mereka pahami?",sample:"Saya akan menggunakan kue kering — 'jika kamu memecah satu kue kering menjadi 4 bagian yang persis sama dan memakan hanya 1 bagian, 1 bagian itu disebut satu-perempat (1/4) dari keseluruhan kue, karena itu 1 dari 4 bagian sama yang kamu mulai.'",explain:"Menyederhanakan konsep angka abstrak menggunakan contoh yang konkret dan relevan menunjukkan pemahaman yang mendalam dan bisa dipindahkan.",hint:"Barang sehari-hari apa yang bisa dipecah secara fisik oleh anak kecil menjadi bagian sama (seperti kue kering) yang akan membantu menjelaskan pecahan?"},
{n:93,type:"open",micro:"Refleksi",q:"Menurutmu mengapa memahami pecahan sebagai 'bagian dari keseluruhan' (menggunakan benda nyata dan gambar dulu) begitu penting sebelum langsung terjun ke aturan dan rumus pecahan abstrak?",sample:"Tanpa dulu benar-benar memahami apa yang secara fisik diwakili sebuah pecahan (seperti benar-benar melihat 3/4 dari pizza), aturan abstrak (seperti mencari penyebut sama atau menyederhanakan) bisa terasa seperti langkah tanpa makna untuk dihafal alih-alih sesuatu yang benar-benar masuk akal — membangun dari pemahaman konkret dan piktorial dulu membantu aturan abstrak itu benar-benar berarti saat kamu menggunakannya nanti.",explain:"Ini mencerminkan wawasan nyata tentang mengapa perjalanan Konkret-Piktorial-Abstrak sangat penting khususnya untuk konsep yang mudah disalahpahami seperti pecahan.",hint:"Akankah aturan pecahan abstrak lebih masuk akal bagi seseorang yang belum pernah benar-benar melihat atau memegang 'bagian dari keseluruhan' nyata, atau bagi seseorang yang sudah pernah?"},
{n:94,type:"open",micro:"Keputusan bisnis menggunakan pecahan",q:"Sebuah toko roti kecil menemukan bahwa 2/5 dari penjualan hariannya berasal dari roti tawar, sementara sisanya berasal dari kue kering. Keputusan bisnis apa yang mungkin didukung data berbasis pecahan ini, dan apa yang masih perlu diwaspadai toko roti tersebut?",sample:"Mereka mungkin menggunakan pecahan itu (2/5 roti tawar, 3/5 kue kering) untuk membantu memutuskan berapa banyak masing-masing yang harus disiapkan setiap hari — tetapi tetap harus waspada bahwa pecahan ini didasarkan pada rata-rata penjualan harian, dan pembagian sebenarnya bisa bervariasi secara nyata dari hari ke hari (seperti lebih banyak roti tawar terjual pada hari tertentu dalam seminggu).",explain:"Menerapkan analisis penjualan berbasis pecahan pada keputusan bisnis nyata, sambil menandai batasan dari satu pecahan rata-rata.",hint:"Apakah pecahan rata-rata berdasarkan penjualan khas menjamin bahwa setiap hari tunggal akan cocok dengan pembagian yang persis sama itu?"},
{n:95,type:"open",micro:"Pecahan bertemu keadilan (membagi tidak merata berdasarkan kontribusi)",q:"Tiga mitra bisnis menginvestasikan jumlah berbeda (1/2, 1/3, dan 1/6 dari total investasi) dan ingin membagi keuntungan sesuai itu alih-alih sama rata. Jelaskan bagaimana pecahan menjamin pembagian yang adil dan proporsional.",sample:"Jika keuntungan dibagi dengan pecahan yang sama seperti investasi setiap mitra (1/2, 1/3, dan 1/6 dari total keuntungan, yang bersama-sama berjumlah tepat 1 keseluruhan), setiap mitra menerima bagian yang proporsional dengan apa yang awalnya mereka investasikan — ini terasa lebih adil bagi banyak orang daripada pembagian tiga arah yang sama rata, karena para mitra tidak berkontribusi secara setara.",explain:"Menghubungkan proporsi pecahan langsung dengan prinsip keadilan nyata berdasarkan kontribusi proporsional alih-alih kesetaraan ketat.",hint:"Apakah ketiga pecahan investasi (1/2, 1/3, 1/6) berjumlah satu keseluruhan penuh, dan apakah membagi keuntungan dengan cara yang sama cocok dengan kontribusi awal setiap mitra?"},
{n:96,type:"open",micro:"Batasan statistik berbasis pecahan",q:"Sebuah laporan menyatakan bahwa '3/4 dari siswa yang disurvei menyukai kebijakan sekolah baru.' Apa yang bisa diberitahukan pecahan ini, dan apa yang tidak bisa diberitahukannya sendiri?",sample:"Ini bisa memberitahumu proporsi dari kelompok yang disurvei secara khusus yang menyatakan menyukai kebijakan itu — tetapi tidak bisa memberitahumu seberapa besar atau representatif kelompok yang disurvei itu sebenarnya (3/4 dari 8 siswa sangat berbeda dari 3/4 dari 800 siswa), atau seberapa kuat siswa itu sebenarnya merasakannya.",explain:"Mengenali bahwa pecahan/proporsi memberikan perbandingan relatif, tetapi tidak otomatis gambaran penuh (ukuran sampel, kekuatan perasaan), adalah koneksi berpikir kritis yang penting.",hint:"Apakah mengetahui '3/4 dari siswa yang disurvei' otomatis memberitahumu berapa total siswa yang sebenarnya disurvei, atau seberapa kuat mereka merasakannya?"},
{n:97,type:"open",micro:"Investigasi nyata multi-langkah",q:"Rancang rencana untuk mengetahui, menggunakan pecahan, kira-kira berapa bagian dari hari khasmu yang dihabiskan untuk berbagai kegiatan (seperti tidur, sekolah, dan waktu luang), tanpa melacak setiap menit dengan sempurna.",sample:"Perkirakan jumlah jam khas yang dihabiskan untuk setiap kegiatan utama, nyatakan masing-masing sebagai pecahan dari hari 24 jam (seperti tidur ≈ 8/24 = 1/3), dan periksa bahwa semua pecahan perkiraanmu berjumlah mendekati keseluruhan hari (1) — sesuaikan perkiraanmu jika jelas tidak, alih-alih perlu melacak setiap menit dengan tepat.",explain:"Menerapkan strategi 'perkirakan pecahan wajar dari suatu keseluruhan, lalu periksa berjumlah mendekati 1' pada jumlah nyata yang sungguh sulit dilacak.",hint:"Bisakah memperkirakan setiap kegiatan sebagai pecahan kasar dari seluruh hari, lalu memeriksa apakah jumlahnya mendekati satu hari penuh, membantu menangkap perkiraan yang tidak realistis?"},
{n:98,type:"open",micro:"Pecahan dan teknologi",q:"Banyak aplikasi resep atau pengukuran nyata secara otomatis menghitung ulang jumlah pecahan saat kamu mengubah ukuran porsi. Apa satu keuntungan dan satu risiko dari sepenuhnya mempercayai penskalaan pecahan otomatis semacam ini?",sample:"Keuntungan: bisa secara instan dan akurat menghitung ulang setiap jumlah bahan pecahan untuk ukuran porsi apa pun, jauh lebih cepat dan andal daripada melakukannya dengan tangan untuk daftar bahan yang panjang. Risiko: jika kamu sendiri tidak memahami matematika pecahan yang mendasarinya, kamu mungkin tidak menyadari jika aplikasi itu memiliki bug atau membulatkan pecahan dengan cara yang sebenarnya tidak masuk akal untuk memasak nyata (seperti membulatkan ke jumlah yang mustahil diukur).",explain:"Memperluas penalaran pecahan ke alat otomatis nyata, menimbang kenyamanan komputasi melawan nilai memahami matematika yang mendasarinya sendiri.",hint:"Jika kamu sendiri tidak memahami penskalaan pecahan, apakah kamu akan bisa menyadari jika perhitungan ulang otomatis sebuah aplikasi terlihat salah atau tidak praktis?"},
{n:99,type:"open",micro:"Menyelidiki klaim pecahan yang bertentangan",q:"Dua label nutrisi resmi berbeda memberikan pecahan yang sedikit berbeda untuk 'nilai harian' sebuah bahan pada produk serupa (keduanya dihitung sebagai suatu jumlah ÷ total rekomendasi harian). Bagaimana seharusnya pembaca yang cermat menyikapi perbedaan seperti ini?",sample:"Pembaca yang cermat sebaiknya menyadari bahwa kedua label itu mungkin membagi dengan nilai 'total rekomendasi harian' yang diasumsikan sedikit berbeda (karena ini bisa bervariasi menurut sumber atau berdasarkan panduan yang sedikit berbeda), bukan karena satu label sekadar salah, dan sebaiknya memeriksa total harian apa yang sebenarnya digunakan setiap pecahan sebelum menyimpulkan salah satu angka salah.",explain:"Menerapkan penalaran yang matang, skeptis namun adil, pada klaim berbasis pecahan yang tampak bertentangan, menghindari kepercayaan buta maupun tuduhan yang tidak adil.",hint:"Bisakah dua label benar-benar tidak sepakat hanya karena mereka membagi dengan total harian asumsi yang sedikit berbeda, bukan karena salah satu membuat kesalahan perhitungan?"},
{n:100,type:"open",micro:"Refleksi kapstone",q:"Melihat kembali skill Pecahan ini — mulai dari memotong benda nyata secara fisik, ke gambar dan garis bilangan, dan akhirnya ke aturan dan operasi pecahan abstrak — kebiasaan apa yang sekarang kamu miliki saat melihat situasi 'bagian dari keseluruhan'?",sample:"Bersifat personal dan terbuka — carilah perubahan nyata, seperti secara otomatis membayangkan pecahan sebagai jumlah fisik nyata (bukan hanya angka abstrak) untuk memeriksa apakah jawaban masuk akal, selalu mencari penyebut sama sebelum menjumlahkan atau mengurangkan, atau menyederhanakan pecahan sebagai langkah terakhir karena kebiasaan.",explain:"Menyebutkan kebiasaan baru yang konkret, terkait perjalanan konkret-ke-abstrak dari skill ini, adalah tanda paling jelas bahwa skill ini sudah tertanam.",hint:"Pikirkan momen dalam unit ini ketika situasi 'bagian dari keseluruhan' berhenti membutuhkan gambar dan mulai masuk akal sebagai pecahan abstrak."},
];
